'use client';
import { Command } from 'cmdk';
import { useEffect, useState } from 'react';

export function {{component_name}}() {
  const [open, setOpen] = useState(false);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.key === 'k' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); setOpen(o => !o); } };
    document.addEventListener('keydown', onKey); return () => document.removeEventListener('keydown', onKey);
  }, []);
  return (
    <Command.Dialog open={open} onOpenChange={setOpen} label="命令面板">
      <Command.Input placeholder="搜尋指令…" />
      <Command.List>
        <Command.Empty>沒有結果</Command.Empty>
        <Command.Item onSelect={() => location.assign('/settings')}>前往設定</Command.Item>
        <Command.Item onSelect={() => location.assign('/profile')}>個人資料</Command.Item>
      </Command.List>
    </Command.Dialog>
  );
}
